const areas={
  capital:{kicker:'RIO DE JANEIRO — CAPITAL',title:'Da Zona Sul à Zona Oeste',copy:'Atendimento em bairros residenciais e comerciais de toda a cidade.',places:['Barra da Tijuca','Recreio dos Bandeirantes','Jacarepaguá','Tijuca','Vila Isabel','Méier','Madureira','Campo Grande','Bangu','Copacabana','Ipanema','Leblon','Botafogo','Flamengo','Laranjeiras','Centro','Santa Teresa','Ilha do Governador']},
  metropolitana:{kicker:'REGIÃO METROPOLITANA',title:'Grande Rio conectado',copy:'Serviços agendados nas principais cidades ao redor da capital.',places:['Niterói','São Gonçalo','Itaboraí','Maricá','Tanguá','Rio Bonito','Cachoeiras de Macacu','Magé','Guapimirim','Duque de Caxias','São João de Meriti','Nilópolis']},
  baixada:{kicker:'BAIXADA FLUMINENSE',title:'Atendimento na Baixada',copy:'Deslocamento planejado para residências, condomínios e empresas.',places:['Nova Iguaçu','Duque de Caxias','Belford Roxo','São João de Meriti','Nilópolis','Mesquita','Queimados','Japeri','Seropédica','Paracambi','Itaguaí','Magé']},
  norte:{kicker:'NORTE FLUMINENSE',title:'Da costa ao interior',copy:'Atendimento sob consulta e agendamento nas cidades do Norte Fluminense.',places:['Campos dos Goytacazes','Macaé','Rio das Ostras','Carapebus','Quissamã','São João da Barra','São Francisco de Itabapoana','Conceição de Macabu']}
};

const renderArea=(key)=>{const area=areas[key];const kicker=document.querySelector('#area-kicker');if(!area||!kicker)return;kicker.textContent=area.kicker;document.querySelector('#area-title').textContent=area.title;document.querySelector('#area-copy').textContent=area.copy;document.querySelector('#area-list').innerHTML=area.places.map(place=>`<li>${place}</li>`).join('');document.querySelectorAll('.area-tabs button').forEach(button=>button.setAttribute('aria-selected',String(button.dataset.area===key)))};

document.querySelectorAll('.area-tabs button').forEach(button=>button.addEventListener('click',()=>renderArea(button.dataset.area)));
renderArea('capital');

const menuButton=document.querySelector('.menu-toggle');
if(menuButton)menuButton.addEventListener('click',()=>{const header=document.querySelector('.site-header');const open=header.classList.toggle('open');menuButton.setAttribute('aria-expanded',String(open))});
document.querySelectorAll('#main-nav a').forEach(link=>link.addEventListener('click',()=>{document.querySelector('.site-header').classList.remove('open');menuButton.setAttribute('aria-expanded','false')}));

fetch('/config.json').then(response=>response.json()).then(config=>{
  const cnpj=document.querySelector('#cnpj');if(cnpj)cnpj.textContent=`CNPJ: ${config.cnpj}`;
  const rawNumber=String(config.whatsappNumber||'').replace(/\D/g,'');
  const number=rawNumber&& !rawNumber.startsWith('55') ? `55${rawNumber}` : rawNumber;
  const message=encodeURIComponent(config.whatsappMessage||'Olá! Gostaria de solicitar um orçamento.');
  if(number){const schema=document.querySelector('#business-schema');if(schema){const data=JSON.parse(schema.textContent);data.telephone=`+${number}`;schema.textContent=JSON.stringify(data)}}
  document.querySelectorAll('.whatsapp-link').forEach(link=>{link.href=number?`https://wa.me/${number}?text=${message}`:'#';if(number){link.target='_blank'}else{link.addEventListener('click',event=>{event.preventDefault();const alert=document.querySelector('#config-alert');alert.hidden=false;clearTimeout(window.configTimer);window.configTimer=setTimeout(()=>alert.hidden=true,5000)})}});
}).catch(()=>{});

const year=document.querySelector('#year');if(year)year.textContent=new Date().getFullYear();
const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.12});
document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));

document.querySelectorAll('details').forEach(item=>item.addEventListener('toggle',()=>{if(item.open)document.querySelectorAll('details[open]').forEach(other=>{if(other!==item)other.open=false})}));

(() => {
  const storageKey = 'jll-chat-conversation';
  const state = { conversation: null, messages: [] };
  const saved = localStorage.getItem(storageKey);
  if (saved) { try { state.conversation = JSON.parse(saved); } catch (_) { localStorage.removeItem(storageKey); } }
  const el = document.createElement('div');
  el.innerHTML = `<button class="chat-launcher" type="button" aria-label="Abrir atendimento online"><span>◔</span><strong>Atendimento online</strong></button>
    <section class="chat-panel" aria-label="Chat JLL Montagens" hidden>
      <header class="chat-header"><div><small>JLL MONTAGENS</small><strong>Atendimento online</strong></div><button class="chat-close" type="button" aria-label="Fechar chat">×</button></header>
      <div class="chat-ticket" hidden></div><div class="chat-body"></div>
      <form class="chat-composer" hidden><input class="chat-file" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" hidden><button class="chat-attach" type="button" aria-label="Anexar foto">＋</button><input name="message" autocomplete="off" placeholder="Digite sua mensagem..." maxlength="2000"><button type="submit" aria-label="Enviar mensagem">➤</button></form>
    </section>`;
  document.body.appendChild(el);
  const launcher = el.querySelector('.chat-launcher'); const panel = el.querySelector('.chat-panel'); const body = el.querySelector('.chat-body'); const composer = el.querySelector('.chat-composer'); const ticket = el.querySelector('.chat-ticket'); const filePicker = composer.querySelector('.chat-file'); const attachButton = composer.querySelector('.chat-attach');
  const escapeHtml = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
  const setOpen = open => { panel.hidden = !open; launcher.setAttribute('aria-expanded', String(open)); if(open) renderHome(); };
  const renderHome = () => { composer.hidden = true; ticket.hidden = true; body.innerHTML = `<div class="chat-welcome"><span class="chat-mark">JLL</span><h2>Olá! Como podemos ajudar?</h2><p>Fale com nossa equipe sobre montagem de móveis e instalação de TV.</p><div class="chat-choice"><button type="button" data-action="new">Novo atendimento <span>→</span></button><button type="button" data-action="resume">Continuar atendimento <span>→</span></button></div>${state.conversation ? '<small class="chat-saved-note">Já existe um atendimento salvo neste dispositivo. Escolha “Continuar atendimento” para recuperá-lo.</small>' : ''}</div>`; };
  const formView = (kind) => { composer.hidden = true; ticket.hidden = true; const resume = kind === 'resume'; body.innerHTML = `<div class="chat-form-view"><button class="chat-back" type="button">← Voltar</button><h2>${resume ? 'Continuar atendimento' : 'Novo atendimento'}</h2><p>${resume ? 'Informe o telefone usado no atendimento para recuperar seu histórico.' : 'Informe seus dados para iniciar uma conversa com um especialista.'}</p>${resume ? '' : '<label>Nome<input name="customerName" autocomplete="name" required></label>'}<label>Telefone<input name="customerPhone" inputmode="tel" autocomplete="tel" placeholder="(21) 99999-9999" required></label><button class="chat-primary" type="button" data-submit="${resume ? 'resume' : 'new'}">${resume ? 'Buscar atendimento' : 'Iniciar conversa'} <span>→</span></button><p class="chat-error" role="alert"></p></div>`; };
  const renderConversation = () => { composer.hidden = false; ticket.hidden = false; ticket.textContent = `Atendimento #${state.conversation.ticketNumber}`; body.innerHTML = `<div class="chat-messages">${state.messages.map(message => `<div class="chat-message ${message.sender_type === 'customer' ? 'from-customer' : 'from-team'}"><span>${escapeHtml(message.body || '')}</span><small>${new Date(message.created_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</small></div>`).join('')}</div>`; const messages = body.querySelector('.chat-messages'); messages.scrollTop = messages.scrollHeight; };
  const request = async (url, payload) => { const response = await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}); const data = await response.json().catch(()=>({})); if(!response.ok){ const error=new Error(data.error || 'Não foi possível concluir.'); error.status=response.status; throw error; } return data; };
  const loadMessages = async () => { const data = await request('/api/conversations/resume',{phone:state.conversation.phone}); state.conversation=data.conversation; state.messages=data.messages || []; localStorage.setItem(storageKey,JSON.stringify(state.conversation)); renderConversation(); };
  el.addEventListener('click', async event => { const action = event.target.closest('[data-action]')?.dataset.action; if(action) return formView(action); if(event.target.closest('.chat-back')) return renderHome(); const submit = event.target.closest('[data-submit]'); if(!submit) return; const form = event.target.closest('.chat-form-view'); const error = form.querySelector('.chat-error'); submit.disabled = true; error.textContent = ''; try { const phone=form.querySelector('[name="customerPhone"]').value; if(submit.dataset.submit === 'resume'){ const data=await request('/api/conversations/resume',{phone}); state.conversation=data.conversation; state.messages=data.messages || []; localStorage.setItem(storageKey,JSON.stringify(state.conversation)); renderConversation(); } else { const data=await request('/api/conversations/create',{name:form.querySelector('[name="customerName"]').value,phone}); if(data.existing){ error.textContent='Já existe um atendimento aberto para este telefone. Recuperar atendimento?'; const confirm=document.createElement('button'); confirm.type='button'; confirm.className='chat-primary'; confirm.textContent='Continuar atendimento'; confirm.onclick=async()=>{state.conversation=data.conversation; await loadMessages();}; form.appendChild(confirm); } else { state.conversation=data.conversation; state.messages=[{sender_type:'system',body:data.message,created_at:new Date().toISOString()}]; localStorage.setItem(storageKey,JSON.stringify(state.conversation)); renderConversation(); } } } catch(exception){ error.textContent=exception.message; submit.disabled=false; if(submit.dataset.submit === 'resume' && exception.status === 404){ const phone=form.querySelector('[name="customerPhone"]').value; const newButton=document.createElement('button'); newButton.type='button'; newButton.className='chat-primary'; newButton.textContent='Abrir novo atendimento'; newButton.onclick=()=>{formView('new'); body.querySelector('[name="customerPhone"]').value=phone;}; form.appendChild(newButton); } } });
  composer.addEventListener('submit', async event => { event.preventDefault(); const input=composer.elements.message; const value=input.value.trim(); if(!value || !state.conversation) return; input.disabled=true; try { const data=await request('/api/conversations/message',{conversationId:state.conversation.id,body:value}); state.messages.push(data.message); input.value=''; renderConversation(); } catch(exception){ alert(exception.message); } finally { input.disabled=false; input.focus(); } });
  const prepareImage = file => new Promise((resolve,reject)=>{ const reader=new FileReader(); reader.onerror=reject; reader.onload=()=>{ const image=new Image(); image.onerror=reject; image.onload=async()=>{ const limit=1800; const scale=Math.min(1,limit/Math.max(image.naturalWidth,image.naturalHeight)); const canvas=document.createElement('canvas'); canvas.width=Math.max(1,Math.round(image.naturalWidth*scale)); canvas.height=Math.max(1,Math.round(image.naturalHeight*scale)); canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height); const qualities=[.86,.74,.62,.5,.4]; let blob=null; for(const quality of qualities){ blob=await new Promise(done=>canvas.toBlob(done,'image/jpeg',quality)); if(blob && blob.size<=3.5*1024*1024) break; } if(!blob) return reject(new Error('Não foi possível preparar a imagem.')); const fileReader=new FileReader(); fileReader.onload=()=>resolve({data:String(fileReader.result).split(',')[1],mimeType:'image/jpeg',fileName:file.name.replace(/\.[^.]+$/,'')+'.jpg'}); fileReader.onerror=reject; fileReader.readAsDataURL(blob); }; image.src=String(reader.result); }; reader.readAsDataURL(file); });
  attachButton.addEventListener('click',()=>filePicker.click());
  filePicker.addEventListener('change',async()=>{const file=filePicker.files?.[0];if(!file||!state.conversation)return;if(!file.type.startsWith('image/')){alert('Escolha uma imagem.');filePicker.value='';return}attachButton.disabled=true;attachButton.textContent='…';try{const prepared=await prepareImage(file);const data=await request('/api/conversations/photo',{conversationId:state.conversation.id,fileName:prepared.fileName,mimeType:prepared.mimeType,data:prepared.data});state.messages.push(data.message);renderConversation()}catch(exception){alert(exception.message)}finally{attachButton.disabled=false;attachButton.textContent='＋';filePicker.value=''}});  launcher.addEventListener('click',()=>setOpen(true)); el.querySelector('.chat-close').addEventListener('click',()=>setOpen(false)); renderHome();
})();



